using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup()
    {
        _cart = new ShoppingCart();
    }

    // ───────────────────────────────────────────────
    // AddItem tests
    // ───────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_CanCalculateTotal()
    {
        // Arrange & Act
        _cart.AddItem("SKU-001", 2, 9.99m);

        // Assert
        Assert.AreEqual(19.98m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_TotalSumsAll()
    {
        // Arrange & Act
        _cart.AddItem("SKU-A", 1, 10.00m);
        _cart.AddItem("SKU-B", 3, 5.00m);
        _cart.AddItem("SKU-C", 2, 7.50m);

        // Assert — 10 + 15 + 15 = 40
        Assert.AreEqual(40.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_QuantityIsAccumulated()
    {
        // Arrange & Act
        _cart.AddItem("SKU-DUP", 2, 5.00m);
        _cart.AddItem("SKU-DUP", 3, 5.00m);

        // Assert — (2+3) * 5 = 25
        Assert.AreEqual(25.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_PriceUsesLatest()
    {
        // Arrange — first add at $5, then add more at $8
        _cart.AddItem("SKU-X", 1, 5.00m);
        _cart.AddItem("SKU-X", 1, 8.00m);

        // Assert — total quantity 2 × latest price $8 = 16
        Assert.AreEqual(16.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null SKU")]
    [DataRow("", DisplayName = "Empty SKU")]
    public void AddItem_NullOrEmptySku_Throws(string? sku)
    {
        // Act & Assert
        Assert.ThrowsException<ArgumentException>(
            () => _cart.AddItem(sku!, 1, 10.00m));
    }

    [TestMethod]
    [DataRow(0, DisplayName = "Zero quantity")]
    [DataRow(-1, DisplayName = "Negative quantity")]
    public void AddItem_NonPositiveQuantity_ThrowsArgumentOutOfRange(int quantity)
    {
        // Act & Assert
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-001", quantity, 10.00m));
        Assert.AreEqual("quantity", ex.ParamName);
    }

    [TestMethod]
    public void AddItem_NegativePrice_ThrowsArgumentOutOfRange()
    {
        // Act & Assert
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-001", 1, -5.00m));
        Assert.AreEqual("price", ex.ParamName);
    }

    [TestMethod]
    public void AddItem_ZeroPrice_DoesNotThrow()
    {
        // Arrange & Act
        _cart.AddItem("FREE", 3, 0.00m);

        // Assert
        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }

    // ───────────────────────────────────────────────
    // RemoveItem tests
    // ───────────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingSku_ItemRemovedFromTotal()
    {
        // Arrange
        _cart.AddItem("SKU-A", 1, 10.00m);
        _cart.AddItem("SKU-B", 2, 5.00m);

        // Act
        _cart.RemoveItem("SKU-A");

        // Assert — only SKU-B remains: 2×5 = 10
        Assert.AreEqual(10.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_OnlyItem_CartBecomesEmpty()
    {
        // Arrange
        _cart.AddItem("SOLO", 1, 25.00m);

        // Act
        _cart.RemoveItem("SOLO");

        // Assert
        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistingSku_ThrowsKeyNotFound()
    {
        // Arrange
        _cart.AddItem("SKU-A", 1, 10.00m);

        // Act & Assert
        Assert.ThrowsException<KeyNotFoundException>(
            () => _cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    public void RemoveItem_EmptyCart_ThrowsKeyNotFound()
    {
        // Act & Assert
        Assert.ThrowsException<KeyNotFoundException>(
            () => _cart.RemoveItem("ANY"));
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null SKU")]
    [DataRow("", DisplayName = "Empty SKU")]
    public void RemoveItem_NullOrEmptySku_Throws(string? sku)
    {
        // Act & Assert
        Assert.ThrowsException<ArgumentException>(
            () => _cart.RemoveItem(sku!));
    }

    [TestMethod]
    public void RemoveItem_ThenReAddSameSku_TotalReflectsNewItem()
    {
        // Arrange
        _cart.AddItem("SKU-R", 2, 10.00m);
        _cart.RemoveItem("SKU-R");

        // Act
        _cart.AddItem("SKU-R", 1, 15.00m);

        // Assert
        Assert.AreEqual(15.00m, _cart.CalculateTotal());
    }

    // ───────────────────────────────────────────────
    // CalculateTotal tests
    // ───────────────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        // Act & Assert
        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsQuantityTimesPrice()
    {
        // Arrange
        _cart.AddItem("WIDGET", 4, 3.25m);

        // Act
        var total = _cart.CalculateTotal();

        // Assert — 4 × 3.25 = 13.00
        Assert.AreEqual(13.00m, total);
    }

    [TestMethod]
    public void CalculateTotal_AfterAddAndRemove_ReflectsCurrentState()
    {
        // Arrange
        _cart.AddItem("A", 1, 100.00m);
        _cart.AddItem("B", 1, 50.00m);
        _cart.AddItem("C", 1, 25.00m);
        _cart.RemoveItem("B");

        // Act
        var total = _cart.CalculateTotal();

        // Assert — 100 + 25 = 125
        Assert.AreEqual(125.00m, total);
    }

    [TestMethod]
    public void CalculateTotal_CalledMultipleTimes_ReturnsSameValue()
    {
        // Arrange
        _cart.AddItem("SKU", 2, 10.00m);

        // Act
        var total1 = _cart.CalculateTotal();
        var total2 = _cart.CalculateTotal();

        // Assert
        Assert.AreEqual(20.00m, total1);
        Assert.AreEqual(total1, total2);
    }

    // ───────────────────────────────────────────────
    // ApplyCoupon tests
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 10, DisplayName = "SAVE10 gives 10% off")]
    [DataRow("SAVE20", 20, DisplayName = "SAVE20 gives 20% off")]
    public void ApplyCoupon_ValidCode_ReducesTotal(string code, int discountPct)
    {
        // Arrange
        _cart.AddItem("ITEM", 1, 100.00m);

        // Act
        _cart.ApplyCoupon(code);
        var total = _cart.CalculateTotal();

        // Assert
        var expected = 100.00m * (1 - discountPct / 100m);
        Assert.AreEqual(expected, total);
    }

    [TestMethod]
    public void ApplyCoupon_Save10_CalculatesTotalCorrectly()
    {
        // Arrange
        _cart.AddItem("A", 2, 15.00m);  // 30
        _cart.AddItem("B", 1, 20.00m);  // 20
        // subtotal = 50

        // Act
        _cart.ApplyCoupon("SAVE10");
        var total = _cart.CalculateTotal();

        // Assert — 50 × 0.90 = 45
        Assert.AreEqual(45.00m, total);
    }

    [TestMethod]
    public void ApplyCoupon_Save20_CalculatesTotalCorrectly()
    {
        // Arrange
        _cart.AddItem("X", 5, 10.00m);  // subtotal = 50

        // Act
        _cart.ApplyCoupon("SAVE20");
        var total = _cart.CalculateTotal();

        // Assert — 50 × 0.80 = 40
        Assert.AreEqual(40.00m, total);
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive_AcceptsMixedCase()
    {
        // Arrange
        _cart.AddItem("ITEM", 1, 100.00m);

        // Act
        _cart.ApplyCoupon("save10");
        var total = _cart.CalculateTotal();

        // Assert
        Assert.AreEqual(90.00m, total);
    }

    [TestMethod]
    [DataRow("INVALID", DisplayName = "Invalid code")]
    [DataRow("SAVE30", DisplayName = "Unsupported discount")]
    [DataRow("EXPIRED", DisplayName = "Non-existent code")]
    public void ApplyCoupon_InvalidCode_ThrowsArgumentException(string code)
    {
        // Act & Assert
        var ex = Assert.ThrowsException<ArgumentException>(
            () => _cart.ApplyCoupon(code));
        Assert.AreEqual("code", ex.ParamName);
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null code")]
    [DataRow("", DisplayName = "Empty code")]
    public void ApplyCoupon_NullOrEmptyCode_Throws(string? code)
    {
        // Act & Assert
        Assert.ThrowsException<ArgumentException>(
            () => _cart.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_SecondCouponReplacesPrevious()
    {
        // Arrange
        _cart.AddItem("ITEM", 1, 100.00m);
        _cart.ApplyCoupon("SAVE20");

        // Act — switch from 20% to 10%
        _cart.ApplyCoupon("SAVE10");
        var total = _cart.CalculateTotal();

        // Assert — 10% off, not 20%
        Assert.AreEqual(90.00m, total);
    }

    [TestMethod]
    public void ApplyCoupon_OnEmptyCart_TotalRemainsZero()
    {
        // Act
        _cart.ApplyCoupon("SAVE20");
        var total = _cart.CalculateTotal();

        // Assert
        Assert.AreEqual(0.00m, total);
    }

    [TestMethod]
    public void ApplyCoupon_ThenAddItems_DiscountApplies()
    {
        // Arrange — apply coupon before adding items
        _cart.ApplyCoupon("SAVE10");

        // Act
        _cart.AddItem("LATE", 2, 50.00m);
        var total = _cart.CalculateTotal();

        // Assert — 100 × 0.90 = 90
        Assert.AreEqual(90.00m, total);
    }

    // ───────────────────────────────────────────────
    // Integration / workflow tests
    // ───────────────────────────────────────────────

    [TestMethod]
    public void FullWorkflow_AddRemoveCoupon_CorrectTotal()
    {
        // Arrange
        _cart.AddItem("A", 2, 10.00m);   // 20
        _cart.AddItem("B", 1, 30.00m);   // 30
        _cart.AddItem("C", 3, 5.00m);    // 15
        // subtotal = 65

        // Act
        _cart.RemoveItem("B");            // subtotal = 35
        _cart.ApplyCoupon("SAVE10");      // 10% off → 31.50
        var total = _cart.CalculateTotal();

        // Assert
        Assert.AreEqual(31.50m, total);
    }

    [TestMethod]
    public void FullWorkflow_AddDuplicateThenCoupon_CorrectTotal()
    {
        // Arrange
        _cart.AddItem("D", 1, 20.00m);
        _cart.AddItem("D", 4, 20.00m);   // qty now 5, total = 100

        // Act
        _cart.ApplyCoupon("SAVE20");      // 20% off → 80
        var total = _cart.CalculateTotal();

        // Assert
        Assert.AreEqual(80.00m, total);
    }
}

