1. namespace Store;
2. 
3. public sealed class ShoppingCart
4. {
5.     private readonly Dictionary<string, (int Quantity, decimal Price)> _items = new();
6.     private decimal _discountPercent;
7. 
8.     public void AddItem(string sku, int quantity, decimal price)
9.     {
10.         ArgumentException.ThrowIfNullOrEmpty(sku);
11. 
12.         if (quantity <= 0)
13.             throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be positive.");
14. 
15.         if (price < 0)
16.             throw new ArgumentOutOfRangeException(nameof(price), "Price cannot be negative.");
17. 
18.         if (_items.TryGetValue(sku, out var existing))
19.             _items[sku] = (existing.Quantity + quantity, price);
20.         else
21.             _items[sku] = (quantity, price);
22.     }
23. 
24.     public void RemoveItem(string sku)
25.     {
26.         ArgumentException.ThrowIfNullOrEmpty(sku);
27. 
28.         if (!_items.Remove(sku))
29.             throw new KeyNotFoundException($"SKU '{sku}' not found in cart.");
30.     }
31. 
32.     public decimal CalculateTotal()
33.     {
34.         var subtotal = _items.Values.Sum(item => item.Quantity * item.Price);
35.         return subtotal * (1 - _discountPercent / 100m);
36.     }
37. 
38.     public void ApplyCoupon(string code)
39.     {
40.         ArgumentException.ThrowIfNullOrEmpty(code);
41. 
42.         _discountPercent = code.ToUpperInvariant() switch
43.         {
44.             "SAVE10" => 10m,
45.             "SAVE20" => 20m,
46.             _ => throw new ArgumentException($"Invalid coupon code: '{code}'.", nameof(code))
47.         };
48.     }
49. }
50.

